// Whether we support the pre-flattened shape pair list which optimizes the common midphase case of collision between particles 
// with only a small number implicit objects each. If so, how many shape pairs do we allow before switching to the generic version?
bool bChaos_Collision_MidPhase_EnableShapePairs = true;
int32 Chaos_Collision_MidPhase_MaxShapePairs = 100;
FAutoConsoleVariableRef CVarChaos_Collision_EnableShapePairs(TEXT("p.Chaos.Collision.EnableShapePairs"), bChaos_Collision_MidPhase_EnableShapePairs, TEXT(""));
FAutoConsoleVariableRef CVarChaos_Collision_MaxShapePairs(TEXT("p.Chaos.Collision.MaxShapePairs"), Chaos_Collision_MidPhase_MaxShapePairs, TEXT(""));

EParticlePairMidPhaseType FParticlePairMidPhase::CalculateMidPhaseType(FGeometryParticleHandle* InParticle0, FGeometryParticleHandle* InParticle1)
{
	// For particles with a small number of shapes, we prebuild the set of potentially colliding
	// shape pairs and cache various data with them. However we don't do this if there are a
	// large number of shapes, or if the geometry hierarchy contains Unions of Unions.
	//
	// @todo(chaos): we should be able to support Unions of Unions in the accelerated path
	// when there aren't many objects (with some changes to FSingleShapePairCollisionDetector)

	// We can force use of the Generic midphase (mainly for testing)
	if (!CVars::bChaos_Collision_MidPhase_EnableShapePairs)
	{
		return EParticlePairMidPhaseType::Generic;
	}

	// How many implicits does each particle have?
	const int32 NumImplicits0 = GetNumLeafImplicits(InParticle0->GetGeometry());
	const int32 NumImplicits1 = GetNumLeafImplicits(InParticle1->GetGeometry());

	// Do we have a ShapeInstance for every implicit object?
	// Only the implicits in the root union are represented in the shapes array
	const bool bIsTree0 = (NumImplicits0 > InParticle0->ShapeInstances().Num());
	const bool bIsTree1 = (NumImplicits1 > InParticle1->ShapeInstances().Num());

	// Are there too many implicits for the flattened shape pair path to be optimal?
	const int32 MaxImplicitPairs = CVars::Chaos_Collision_MidPhase_MaxShapePairs;
	const bool bTooManyImplicitPairs = (MaxImplicitPairs > 0) && (NumImplicits0 * NumImplicits1 > MaxImplicitPairs);

	// Is either of the implicits a Union of Unions?
	const bool bIsTree = bIsTree0 || bIsTree1;

	const bool bCanPrebuildShapePairs = !bTooManyImplicitPairs && !bIsTree;

	// If both particles have one-way interaction enabled, we might want to treat them as spheres
	if (bCanPrebuildShapePairs && (CVars::ChaosOneWayInteractionPairCollisionMode == (int32)EOneWayInteractionPairCollisionMode::SphereCollision))
	{
		const bool bIsOneWay0 = FConstGenericParticleHandle(InParticle0)->OneWayInteraction();
		const bool bIsOneWay1 = FConstGenericParticleHandle(InParticle1)->OneWayInteraction();
		if (bIsOneWay0 && bIsOneWay1)
		{
			return EParticlePairMidPhaseType::SphereApproximation;
		}
	}

	// If we have two small flat hierarchies we will expand and prefilter all shape pairs
	if (bCanPrebuildShapePairs)
	{
		return EParticlePairMidPhaseType::ShapePair;
	}

	// We have at least one complicated geometry hierarchy so use the general purpose midphase
	return EParticlePairMidPhaseType::Generic;
}

void FShapePairParticlePairMidPhase::BuildDetectorsImpl()
{
	if (IsValid() && (Particle0 != Particle1))
	{
		const FShapesArray& Shapes0 = Particle0->ShapesArray();
		const FShapesArray& Shapes1 = Particle1->ShapesArray();
		for (int32 ShapeIndex0 = 0; ShapeIndex0 < Shapes0.Num(); ++ShapeIndex0)
		{
			const FPerShapeData* Shape0 = Shapes0[ShapeIndex0].Get();
			for (int32 ShapeIndex1 = 0; ShapeIndex1 < Shapes1.Num(); ++ShapeIndex1)
			{
				const FPerShapeData* Shape1 = Shapes1[ShapeIndex1].Get();
				TryAddShapePair(Shape0, ShapeIndex0, Shape1, ShapeIndex1);
			}
		}
	}
}

void FShapePairParticlePairMidPhase::TryAddShapePair(const FPerShapeData* Shape0, const int32 ShapeIndex0, const FPerShapeData* Shape1, const int32 ShapeIndex1)
{
	const FImplicitObject* Implicit0 = Shape0->GetLeafGeometry();
	const EImplicitObjectType ImplicitType0 = Private::GetImplicitCollisionType(Particle0, Implicit0);

	const FImplicitObject* Implicit1 = Shape1->GetLeafGeometry();
	const EImplicitObjectType ImplicitType1 = Private::GetImplicitCollisionType(Particle1, Implicit1);

	const bool bDoPassFilter = ShapePairNarrowPhaseFilter(ImplicitType0, Shape0, ImplicitType1, Shape1);
	if (bDoPassFilter)
	{
		bool bSwap = false;
		const EContactShapesType ShapePairType = Collisions::CalculateShapePairType(Particle0, Implicit0, Particle1, Implicit1, bSwap);

		if (ShapePairType != EContactShapesType::Unknown)
		{
			if (!bSwap)
			{
				const Private::FCollisionSortKey CollisionSortKey = Private::FCollisionSortKey(Particle0, ShapeIndex0, Particle1, ShapeIndex1);
				ShapePairDetectors.Emplace(FSingleShapePairCollisionDetector(Particle0, Shape0, Particle1, Shape1, CollisionSortKey, ShapePairType, *this));
			}
			else
			{
				const Private::FCollisionSortKey CollisionSortKey = Private::FCollisionSortKey(Particle1, ShapeIndex1, Particle0, ShapeIndex0);
				ShapePairDetectors.Emplace(FSingleShapePairCollisionDetector(Particle1, Shape1, Particle0, Shape0, CollisionSortKey, ShapePairType, *this));
			}
		}
		else
		{
			// If we get here we have a Union of Unions, but that means we should have created 
			// a FGenericParticlePairMidPhase. See CalculateMidPhaseType
			ensure(false);
		}
	}
}

int32 FShapePairParticlePairMidPhase::GenerateCollisionsImpl(
	const FRealSingle Dt,
	const FRealSingle CullDistance,
	const FVec3f& RelativeMovement,
	const FCollisionContext& Context)
{
	CHAOS_MIDPHASE_SCOPE_CYCLE_TIMER(FShapePairParticlePairMidPhase_GenerateCollision);

	//TRACE_COUNTER_INCREMENT(ChaosTraceCounter_MidPhase_NumShapePair);

	int32 NumActive = 0;
	if (Flags.bIsCCDActive != 0)
	{
		for (FSingleShapePairCollisionDetector& ShapePair : ShapePairDetectors)
		{
			NumActive += ShapePair.GenerateCollisionCCD(Dt, CullDistance, RelativeMovement, Flags.bUseSweep, Context);
		}
	}
	else
	{
		for (FSingleShapePairCollisionDetector& ShapePair : ShapePairDetectors)
		{
			NumActive += ShapePair.GenerateCollision(Dt, CullDistance, RelativeMovement, Context);
		}
	}
	return NumActive;

	// the Epoch.
	++CurrentEpoch;

	for (const TUniquePtr<FCollisionContextAllocator>& ContextAllocator : ContextAllocators)
	{
		ContextAllocator->BeginDetectCollisions(CurrentEpoch);
	}

	ResetActiveConstraints();

	// Clear the collision list for this tick - we are about to rebuild them
	ActiveConstraints.Reset();
	ActiveCCDConstraints.Reset();
}

void FCollisionConstraintAllocator::ProcessNewConstraints()
{
	QUICK_SCOPE_CYCLE_COUNTER(STAT_Collisions_ProcessNewConstraints);
	FMemMark Mark(FMemStack::Get());

	if (!ContextAllocators.IsEmpty())
	{
		const TArray<FPBDCollisionConstraint*>& NewConstraints = ContextAllocators[0]->NewActiveConstraints;
		ActiveConstraints.Append(NewConstraints);

		ProcessNewNonCcdConstraints(NewConstraints, ActiveCCDConstraints);
		ProcessNewCcdConstraints();

	if (!InParams.Geometry->ConvexElems.IsEmpty())
	{
		// Extract the scale from the transform - we have separate wrapper classes for scale versus translate/rotate 
		FVector NetScale = Scale * InParams.LocalTransform.GetScale3D();

		// If Scale is zero in any component, set minimum positive instead
		NetScale.X = FMath::Abs(NetScale.X) < UE_KINDA_SMALL_NUMBER ? UE_KINDA_SMALL_NUMBER : NetScale.X;
		NetScale.Y = FMath::Abs(NetScale.Y) < UE_KINDA_SMALL_NUMBER ? UE_KINDA_SMALL_NUMBER : NetScale.Y;
		NetScale.Z = FMath::Abs(NetScale.Z) < UE_KINDA_SMALL_NUMBER ? UE_KINDA_SMALL_NUMBER : NetScale.Z;

		const FVector NetScaleAbs = NetScale.GetAbs();

		const FTransform ConvexTransform = FTransform(InParams.LocalTransform.GetRotation(), Scale * InParams.LocalTransform.GetTranslation(), FVector(1, 1, 1));
		const bool bHasTranslationOrRotation = !ConvexTransform.GetTranslation().IsNearlyZero() || !ConvexTransform.GetRotation().IsIdentity();
		const bool bNoScale = NetScale == FVector(1);

		for (const FKConvexElem& CollisionBody : InParams.Geometry->ConvexElems)
		{
			if (const auto& ConvexImplicit = CollisionBody.GetChaosConvexMesh())
			{
				const FVector ScaledSize = (NetScaleAbs * CollisionBody.ElemBox.GetSize());	// Note: Scale can be negative
				const Chaos::FReal CollisionMargin = FMath::Min<Chaos::FReal>(ScaledSize.GetMin() * CollisionMarginFraction, CollisionMarginMax);

				// Wrap the convex in a scaled or instanced wrapper depending on scale value, and add a margin
				// NOTE: CollisionMargin is on the Instance/Scaled wrapper, not the inner convex (which is shared and should not have a margin).
				Chaos::FImplicitObjectPtr Implicit;
				if (bNoScale)
				{
					Implicit = MakeImplicitObjectPtr<Chaos::TImplicitObjectInstanced<Chaos::FConvex>>(ConvexImplicit, CollisionMargin);
				}
				else
				{
					Implicit = MakeImplicitObjectPtr<Chaos::TImplicitObjectScaled<Chaos::FConvex>>(ConvexImplicit, NetScale, CollisionMargin);
				}

				// Wrap the convex in a non-scaled transform if necessary (the scale is pulled out above)
				if (bHasTranslationOrRotation)
				{
					Implicit = MakeImplicitObjectPtr<Chaos::TImplicitObjectTransformed<Chaos::FReal, 3>>(MoveTemp(Implicit), ConvexTransform);
				}

				TUniquePtr<Chaos::FPerShapeData> NewShape = NewShapeHelper(Implicit, Shapes.Num(), (void*)CollisionBody.GetUserData(), CollisionBody.GetCollisionEnabled());
				Shapes.Emplace(MoveTemp(NewShape));
				Geoms.Emplace(MoveTemp(Implicit));
			}
		}
	}
}

if (bMakeComplexGeometry)
{
	const FTransform MeshTransform = FTransform(InParams.LocalTransform.GetRotation(), Scale * InParams.LocalTransform.GetTranslation(), FVector(1, 1, 1));
	const bool bHasTranslationOrRotation = !MeshTransform.GetTranslation().IsNearlyZero() || !MeshTransform.GetRotation().IsIdentity();

    !shapes.is_empty(),
    "A compound shape must contain at least one shape."
);
let mut aabbs = Vec::new();
let mut leaves = Vec::new();
let mut aabb = Aabb::new_invalid();

for (i, (delta, shape)) in shapes.iter().enumerate() {
    let bv = shape.compute_aabb(delta);

    aabb.merge(&bv);
    aabbs.push(bv);
    leaves.push((i, bv));

    if shape.as_composite_shape().is_some() {
        panic!("Nested composite shapes are not allowed.");
    }
}

// NOTE: we apply no dilation factor because we won't
// update this tree dynamically.

let mut color_index = COLOR_OVERFLOW_INDEX;

// TODO: We could allow forcing overflow by making this optional.
if !is_static1 && !is_static2 {
    // Constraints involving only non-static bodies cannot be in colors reserved
    // for constraints involving static bodies. This helps reduce tunneling through
    // static geometry by solving static contacts last.
    for i in 0..DYNAMIC_COLOR_COUNT {
        let color = &mut self.colors[i];
        if color.body_set.get(body1.index_u32() as usize)
            || color.body_set.get(body2.index_u32() as usize)
        {
            continue;
        }

        color.body_set.set_and_grow(body1.index_u32() as usize);
        color.body_set.set_and_grow(body2.index_u32() as usize);
        color_index = i;
        break;
    }
} else if !is_static1 {
    // Build static colors from the end to give them higher priority.
    for i in (1..COLOR_OVERFLOW_INDEX).rev() {
        let color = &mut self.colors[i];
        if color.body_set.get(body1.index_u32() as usize) {
            continue;
        }

        color.body_set.set_and_grow(body1.index_u32() as usize);
        color_index = i;
        break;
    }
} else if !is_static2 {
    // Build static colors from the end to give them higher priority.
    for i in (1..COLOR_OVERFLOW_INDEX).rev() {
        let color = &mut self.colors[i];
        if color.body_set.get(body2.index_u32() as usize) {
            continue;
        }

        color.body_set.set_and_grow(body2.index_u32() as usize);
        color_index = i;
        break;
    }
}

// Add a constraint handle to the contact edge.
let color = &mut self.colors[color_index];
let manifold_index = contact_edge.constraint_handles.len();
contact_edge
    .constraint_handles
    .push(ContactConstraintHandle {
        color_index: color_index as u8,
        local_index: color.manifold_handles.len(),
    });

// Add the handle of the contact manifold to the color.
color.manifold_handles.push(ContactManifoldHandle {
    contact_id: contact_pair.contact_id,
    manifold_index,
});

    let delta_secs = time.delta_seconds_adjusted();
    let max_overlap_solve_speed = solver_config.max_overlap_solve_speed * length_unit.0;

    // Solve overflow constraints serially. They have lower priority, so they are solved first.
    for constraint in constraint_graph.colors[COLOR_OVERFLOW_INDEX]
        .contact_constraints
        .iter_mut()
    {
        solve_contacts_internal::<USE_BIAS>(
            &bodies,
            constraint,
            max_overlap_solve_speed,
            delta_secs,
        );
    }

    // Solve contact constraints in each color in parallel.
    for color in constraint_graph
        .colors
        .iter_mut()
        .take(COLOR_OVERFLOW_INDEX)
        .filter(|color| !color.contact_constraints.is_empty())
    {
        crate::utils::par_for_each(&mut color.contact_constraints, 64, |_i, constraint| {
            solve_contacts_internal::<USE_BIAS>(
                &bodies,
                constraint,
                max_overlap_solve_speed,
                delta_secs,
            );
        });
    }

    if USE_BIAS {
        diagnostics.solve_constraints += start.elapsed();
    } else {
        diagnostics.relax_velocities += start.elapsed();
    }
}

// Use the collider's own collision margin if specified, and fall back to the body's
// collision margin.
//
// The collision margin adds artificial thickness to colliders for performance
// and stability. See the `CollisionMargin` documentation for more details.
let collision_margin1 = collider1
    .collision_margin
    .or(rb_collision_margin1)
    .map_or(0.0, |margin| margin.0);
let collision_margin2 = collider2
    .collision_margin
    .or(rb_collision_margin2)
    .map_or(0.0, |margin| margin.0);
let collision_margin_sum = collision_margin1 + collision_margin2;

// Use the collider's own speculative margin if specified, and fall back to the body's
// speculative margin.
//
// The speculative margin is used to predict contacts that might happen during the frame.
// This is used for speculative collision. See the CCD and `SpeculativeMargin` documentation
// for more details.
let speculative_margin1 = collider1
    .speculative_margin
    .map_or(rb_speculative_margin1.map(|margin| margin.0), |margin| {
        Some(margin.0)
    });
let speculative_margin2 = collider2
    .speculative_margin
    .map_or(rb_speculative_margin2.map(|margin| margin.0), |margin| {
        Some(margin.0)
    });

let relative_linear_velocity: Vector;

// Compute the effective speculative margin, clamping it based on velocities and the maximum bound.
let effective_speculative_margin = {
    let speculative_margin1 =
        speculative_margin1.unwrap_or(*self.default_speculative_margin);
    let speculative_margin2 =
        speculative_margin2.unwrap_or(*self.default_speculative_margin);
    let inv_delta_secs = delta_secs.recip();

    // Clamp velocities to the maximum speculative margins.
    if speculative_margin1 < Scalar::MAX {
        lin_vel1 = lin_vel1.clamp_length_max(speculative_margin1 * inv_delta_secs);
    }
    if speculative_margin2 < Scalar::MAX {
        lin_vel2 = lin_vel2.clamp_length_max(speculative_margin2 * inv_delta_secs);
    }

    // Compute the effective margin based on how much the bodies
    // are expected to move relative to each other.
    relative_linear_velocity = lin_vel2 - lin_vel1;
    delta_secs * relative_linear_velocity.length()
};

// The maximum distance at which contacts are detected.
// At least as large as the contact tolerance.
let max_contact_distance = effective_speculative_margin
    .max(*self.contact_tolerance)
    + collision_margin_sum;

let was_touching = contacts.flags.contains(ContactPairFlags::TOUCHING);

// Save the old manifolds for warm starting.
let old_manifolds = contacts.manifolds.clone();

// TODO: It'd be good to persist the manifolds and let Parry match contacts.
//       This isn't currently done because it requires using Parry's contact manifold type.
// Compute the contact manifolds using the effective speculative margin.
